/* MSG-01 · Lista de Hilos — estilos de la pantalla.
   Paleta cerrada: todo color sale de var(--bw-*). */

.screen {
  font-family: var(--bw-font-body);
  color: var(--bw-ink-steel);
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin: 0 0 16px;
  max-width: 560px;
}

/* Barra de acciones ---------------------------------------------------- */

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-family: inherit;
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  background: var(--bw-warm-cream);
  outline: none;
  transition: border-color 0.15s ease;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.contactWrap {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  flex-shrink: 0;
}

.newContactBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  border: none;
  border-radius: 5px;
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s ease;
}

.newContactBtn:hover:not(:disabled) {
  opacity: 0.88;
}

.newContactBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* Motivo visible del botón deshabilitado: el Directorio (DIR-01) queda fuera
   del alcance del MVP y el control no debe parecer pulsable sin explicación. */
.scopeNote {
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.pagInfo {
  margin-left: auto;
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

/* Estados de la consulta ------------------------------------------------ */

.loadingBox {
  padding: 28px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  text-align: center;
  font-size: var(--bw-size-input);
  color: var(--bw-text-secondary);
}

.errorBox {
  margin-bottom: 14px;
  padding: 10px 12px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-error-text);
}

/* Paginación ------------------------------------------------------------ */

.pagination {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
}

.pageButton {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  font-family: inherit;
  font-size: var(--bw-size-label);
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.12s ease, color 0.12s ease;
}

.pageButton:hover:not(:disabled):not(.active) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageButton:disabled {
  opacity: 0.55;
  cursor: default;
}

.active {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

