import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  type ThreadPage,
} from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — pantalla.
 *
 * Posee el estado de búsqueda, de página y de carga; importa la capa de datos y
 * delega el dibujo de las filas en `ThreadList` (presentacional).
 */

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * Firma pública cableada por el shell. MSG-02 no está en el alcance del MVP
   * (Plan §9), así que abrir un hilo no tiene destino: se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/** La apertura de un hilo no hace nada en MSG-01: no hay MSG-02. */
const IGNORE_THREAD_OPEN = () => {
  /* Intencionadamente vacío. */
};

/**
 * Convierte un fallo de red en texto legible.
 *
 * PostgREST no lanza `Error`: rechaza con un objeto plano `{ code, message }`.
 * `String(e)` daría `[object Object]` y `e.message` daría `undefined`; hay que
 * sacar `code` y/o `message` cuando existan y pintarlos (F-128).
 */
function errorDetail(e: unknown): string {
  if (e instanceof Error) {
    return e.message || 'Error desconocido';
  }
  if (e !== null && typeof e === 'object') {
    const record = e as Record<string, unknown>;
    const code = typeof record.code === 'string' ? record.code : '';
    const message = typeof record.message === 'string' ? record.message : '';
    const parts = [code, message].filter(Boolean);
    if (parts.length > 0) return parts.join(': ');
  }
  if (typeof e === 'string') return e;
  return String(e);
}

export function Messages({ profile, now, onOpenThread }: MessagesProps) {
  // La prop existe como contrato público del componente; no se usa en MSG-01.
  void onOpenThread;

  const [query, setQuery] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let alive = true;
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (!alive) return;
        setData(result);
      })
      .catch((e: unknown) => {
        if (!alive) return;
        setError(e);
      });

    return () => {
      alive = false;
    };
  }, [profile.orgId, search, page]);

  function submitSearch() {
    setSearch(query.trim());
    setPage(1);
  }

  const totalPages = data ? Math.max(1, pageCount(data.total)) : 1;
  const threadWord = data && data.total === 1 ? 'hilo' : 'hilos';

  return (
    <section className={styles.screen}>
      <div className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</div>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            value={query}
            placeholder="Buscar por nombre de organización..."
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') submitSearch();
            }}
          />
        </div>

        <div className={styles.contactWrap}>
          <button
            type="button"
            className={styles.newContactBtn}
            disabled
            aria-describedby="directorio-scope"
          >
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span
            id="directorio-scope"
            data-testid="directorio-scope"
            className={styles.scopeNote}
          >
            El Directorio queda fuera del MVP.
          </span>
        </div>

        {data && (
          <span className={styles.pagInfo} data-testid="pag-info">
            {data.total} {threadWord} · Página {page} de {totalPages}
          </span>
        )}
      </div>

      {error !== null ? (
        <div role="alert" className={styles.errorBox}>
          <strong>No se pudieron cargar los hilos.</strong> {errorDetail(error)}
        </div>
      ) : !data ? (
        <div className={styles.loadingBox}>Cargando hilos…</div>
      ) : (
        <ThreadList threads={data.threads} now={now} onOpen={IGNORE_THREAD_OPEN} />
      )}

      {data && (
        <nav className={styles.pagination} aria-label="Paginación de hilos">
          <button
            type="button"
            className={styles.pageButton}
            aria-label="Página anterior"
            disabled={page === 1}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            ‹
          </button>

          {Array.from({ length: totalPages }, (_, i) => i + 1).map((pageNumber) => (
            <button
              key={pageNumber}
              type="button"
              className={
                pageNumber === page
                  ? `${styles.pageButton} ${styles.active}`
                  : styles.pageButton
              }
              aria-current={pageNumber === page ? 'page' : undefined}
              onClick={() => setPage(pageNumber)}
            >
              {pageNumber}
            </button>
          ))}

          <button
            type="button"
            className={styles.pageButton}
            aria-label="Página siguiente"
            disabled={page === totalPages}
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
          >
            ›
          </button>
        </nav>
      )}
    </section>
  );
}

