/* MSG-01 · Lista de hilos — estilos de la lista y del estado vacío.
   Paleta cerrada: todo color sale de var(--bw-*). */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
  transition: background-color 0.1s ease;
}

.row:last-child {
  border-bottom: none;
}

.row:hover {
  background-color: var(--bw-row-hover-tint);
}

.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  gap: 5px 12px;
  align-items: center;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  color: inherit;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
}

.rowButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.country {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.rowMeta {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-self: end;
}

.time {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  flex: 1;
  font-size: 12px;
  color: var(--bw-steel-mist);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.state {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
}

.stateNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.stateInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.stateWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.stateSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.stateClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* Estado vacío: va en un contenedor propio, fuera de cualquier <ul>, para que no
   quede ningún rol `listitem` en el documento cuando no hay hilos (F-141). */
.emptyState {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 44px 24px;
  text-align: center;
}

.emptyText {
  margin: 0 0 16px;
  font-size: var(--bw-size-input);
  color: var(--bw-text-secondary);
}

.emptyCta {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  border: none;
  border-radius: 5px;
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  opacity: 0.55;
  cursor: not-allowed;
}

.emptyReason {
  display: block;
  margin-top: 8px;
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  color: var(--bw-input-placeholder);
}

