import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * MSG-01 · Lista de hilos — presentacional.
 *
 * Recibe una página de hilos ya cargada y la pinta en el orden en que la recibe
 * (el orden lo decide el servidor, `last_item_at` descendente). No consulta la
 * base de datos ni posee estado.
 *
 * Cada fila es un `<li>` que conserva su rol implícito `listitem`; lo pulsable es
 * el `<button>` que hay DENTRO del `<li>` (F-131). Un `role` explícito sobre el
 * `<li>` sustituiría al rol implícito y rompería el contrato.
 */

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (threadId: string) => void;
}

/**
 * Tono del badge → clase CSS.
 *
 * El tipo es `string | undefined` a propósito (F-143): cualquier propiedad de un
 * módulo CSS puede no existir bajo `noUncheckedIndexedAccess`. El `?? ''` del
 * punto de consumo es lo que convierte ese posible hueco en «sin clase», nunca en
 * la palabra `undefined`.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.stateNeutral,
  info: styles.stateInfo,
  warn: styles.stateWarn,
  success: styles.stateSuccess,
  closed: styles.stateClosed,
};

function timeLabel(iso: string, now?: Date | undefined): string {
  // relativeTime ya tiene `now = new Date()` de respaldo en la capa de datos;
  // pero su parámetro no acepta `undefined` explícito, así que se omite.
  if (now === undefined) return relativeTime(iso);
  return relativeTime(iso, now);
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyCta} disabled>
          Ir al Directorio
        </button>
        {/* El motivo visible del botón apagado (F-128): sin esto, un control
            deshabilitado sin explicación parece un error de interfaz. */}
        <span className={styles.emptyReason}>El Directorio queda fuera del MVP.</span>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.org}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry !== '' && (
                  <span className={styles.country}>{thread.counterpartyCountry}</span>
                )}
              </span>
              <span className={styles.rowMeta}>
                <span className={styles.time}>{timeLabel(thread.lastItemAt, now)}</span>
              </span>
              <span className={styles.rowBottom}>
                {/* La vista previa son metadatos en claro, nunca contenido
                    descifrado (spec §7 / F-027). */}
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.state} ${tone}`}>{thread.state}</span>
              </span>
              {/* Cuarta celda vacía del grid: la columna derecha de la segunda
                  fila no tiene contenido en esta versión sin recuento de no
                  leídos (F-027). */}
            </button>
          </li>
        );
      })}
    </ul>
  );
}
